import xml.etree.ElementTree as ET


def decode_inventory(xml_text):
    if not isinstance(xml_text, str):
        raise ValueError("xml_text must be a string")
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError("malformed XML") from exc
    if root.tag != "inventory" or root.attrib or (root.text or "").strip():
        raise ValueError("invalid root")
    result = []
    shared_details = {}
    for element in root:
        if element.tag != "item" or set(element.attrib) != {"code", "quantity"} or list(element):
            raise ValueError("invalid item")
        code = element.attrib["code"]
        quantity_text = element.attrib["quantity"]
        if not code or not quantity_text.isascii() or not quantity_text.isdecimal():
            raise ValueError("invalid item attributes")
        shared_details["description"] = (element.text or "").strip()
        result.append({"code": code, "quantity": int(quantity_text), "details": shared_details})
        if (element.tail or "").strip():
            raise ValueError("unexpected text")
    return result
```

